def link_existing_movements(apps, schema_editor):
    """Point the lines of documents already posted at the stock they moved.

    Until now a direct invoice's issue, its return on cancellation and a
    credit note's return were found by the document's number. From here on
    each line names its own movement, so the movements made before are linked
    once, here: for every stocked line, the first movement of the same kind,
    product and quantity that carries the document's number and no other line
    has claimed. A number two documents shared is resolved in the order the
    documents were created, which is the order their movements were made.
    """
    Invoice = apps.get_model("sales", "Invoice")
    InvoiceLine = apps.get_model("sales", "InvoiceLine")
    StockMovement = apps.get_model("inventory", "StockMovement")
    claimed = set()

    def claim(line, invoice, movement_type):
        candidates = StockMovement.objects.filter(
            product_id=line.product_id, product__company_id=invoice.company_id,
            movement_type=movement_type, sales_order__isnull=True,
            reference=invoice.reference, quantity=line.quantity,
        ).order_by("created_at", "pk")
        for movement in candidates:
            if movement.pk not in claimed:
                claimed.add(movement.pk)
                return movement
        return None

    papers = Invoice.objects.filter(sales_order__isnull=True).exclude(
        status="DRAFT").order_by("created_at", "pk")
    for invoice in papers:
        is_note = invoice.original_invoice_id is not None or invoice.status == "CREDIT_NOTE"
        if is_note and not invoice.goods_returned:
            continue
        lines = InvoiceLine.objects.filter(
            invoice=invoice, product__isnull=False,
            product__track_inventory=True).order_by("pk")
        for line in lines:
            fields = []
            if line.stock_movement_id is None:
                movement = claim(line, invoice, "RETURN_IN" if is_note else "DELIVERY")
                if movement is not None:
                    line.stock_movement = movement
                    fields.append("stock_movement")
            if not is_note and invoice.status == "CANCELLED" and line.stock_return_id is None:
                movement = claim(line, invoice, "RETURN_IN")
                if movement is not None:
                    line.stock_return = movement
                    fields.append("stock_return")
            if fields:
                line.save(update_fields=fields)


